"""Shared primitives: block hashing and JSONL reading."""
import hashlib
import json


def compute_block_hash(block: dict) -> str:
    """sha256 over the canonical JSON of the block without its hash field."""
    payload = {k: v for k, v in block.items() if k != "hash"}
    blob = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(blob).hexdigest()


def verify_block_hash(block: dict) -> bool:
    return block.get("hash") == compute_block_hash(block)


def iter_jsonl(path):
    """Yield (offset_after_line, obj) for each complete JSONL line.

    A trailing partial line (no newline) is not consumed, so a crashed
    writer never makes us index half a block.
    """
    with open(path, "r", encoding="utf-8") as f:
        while True:
            line = f.readline()
            if not line:
                return
            if not line.endswith("\n"):
                return
            offset = f.tell()
            line = line.strip()
            if not line:
                continue
            yield offset, json.loads(line)
